package liftdispatch

import "errors"

type sim struct {
	pickup, drop []int64
	reqT         []int64
	finish       int64
	moved        int64
	stops        []int64
}

func sign(x int64) int64 {
	if x > 0 {
		return 1
	}
	if x < 0 {
		return -1
	}
	return 0
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func simulate(floors int64, requests []int64) (*sim, error) {
	if floors < 2 || floors > 100 || len(requests)%3 != 0 {
		return nil, errors.New("bad input")
	}
	n := len(requests) / 3
	t := make([]int64, n)
	from := make([]int64, n)
	to := make([]int64, n)
	for i := 0; i < n; i++ {
		t[i], from[i], to[i] = requests[3*i], requests[3*i+1], requests[3*i+2]
		if t[i] < 0 || t[i] > 100000 || from[i] < 0 || from[i] >= floors || to[i] < 0 || to[i] >= floors || from[i] == to[i] {
			return nil, errors.New("bad request")
		}
	}
	s := &sim{pickup: make([]int64, n), drop: make([]int64, n), reqT: t, stops: []int64{}}
	status := make([]int, n) // 0 future, 1 waiting, 2 riding, 3 done
	var floor, d, now, done int64
	for done < int64(n) {
		for i := 0; i < n; i++ {
			if status[i] == 0 && t[i] == now {
				status[i] = 1
			}
		}
		acted := false
		for i := 0; i < n; i++ {
			if status[i] == 2 && to[i] == floor {
				status[i] = 3
				s.drop[i] = now
				done++
				acted = true
			}
		}
		if done == int64(n) {
			s.stops = append(s.stops, floor)
			break
		}
		if d != 0 {
			ahead := false
			for i := 0; i < n; i++ {
				if (status[i] == 2 && sign(to[i]-floor) == d) || (status[i] == 1 && sign(from[i]-floor) == d) {
					ahead = true
					break
				}
			}
			if !ahead {
				d = 0
			}
		}
		first := -1
		for i := 0; i < n; i++ {
			if status[i] == 1 && from[i] == floor {
				first = i
				break
			}
		}
		if first >= 0 {
			sd := d
			if sd == 0 {
				sd = sign(to[first] - floor)
			}
			boarded := false
			for i := 0; i < n; i++ {
				if status[i] == 1 && from[i] == floor && sign(to[i]-floor) == sd {
					status[i] = 2
					s.pickup[i] = now
					boarded = true
				}
			}
			if boarded {
				acted = true
				if d == 0 {
					d = sd
				}
			}
		}
		if acted {
			s.stops = append(s.stops, floor)
		}
		var nearUp, nearDown int64 = -1, -1
		for i := 0; i < n; i++ {
			var target int64
			switch status[i] {
			case 1:
				target = from[i]
			case 2:
				target = to[i]
			default:
				continue
