			switch {
			case up && down:
				if nearUp <= nearDown {
					d = 1
				} else {
					d = -1
				}
			case up:
				d = 1
			case down:
				d = -1
			}
		}
		floor += d
		s.moved += abs(d)
		now++
	}
	if n > 0 {
		s.finish = now
	}
	return s, nil
}

